#include "frontend/common/ai2_frontend_session.h"
#include <stdio.h>
#include <stdlib.h>
static unsigned long long frame_hash(const uint32_t*p,size_t n){unsigned long long h=1469598103934665603ull;size_t i;for(i=0;i<n;i++){uint32_t v=p[i];unsigned j;for(j=0;j<4u;j++){h^=(unsigned char)(v>>(8u*j));h*=1099511628211ull;}}return h;}
int main(int argc,char**argv){Ai2FrontendSession s;Ai2FrameResult r;Ai2CoreObservation o;uint32_t *pixels;unsigned frames=2u,i;char error[256]={0};if(argc<2||argc>3){fprintf(stderr,"usage: %s ROM.nes [frames]\n",argv[0]);return 2;}if(argc==3)frames=(unsigned)strtoul(argv[2],NULL,10);if(!ai2_frontend_session_open(&s,argv[1],error,sizeof(error))){fprintf(stderr,"%s\n",error);return 3;}for(i=0;i<frames;i++)if(!ai2_frontend_session_advance(&s,0u,0u,&r)){ai2_frontend_session_close(&s);return 4;}pixels=(uint32_t*)malloc((size_t)AI2_CORE_FRAME_PIXELS*sizeof(*pixels));if(!pixels||!ai2_frontend_session_copy_bgra(&s,pixels,AI2_CORE_FRAME_PIXELS)||!ai2_static_core_observe(s.core,&o)){free(pixels);ai2_frontend_session_close(&s);return 5;}printf("mode=headed-boundary frames=%llu pc=%04X bank=%u instructions=%llu frame_hash=%016llx audio=%zu\n",(unsigned long long)o.frames,o.program_counter,o.physical_prg_bank,(unsigned long long)o.executed_instructions,frame_hash(pixels,AI2_CORE_FRAME_PIXELS),o.pcm_available);free(pixels);ai2_frontend_session_close(&s);return 0;}
